import json, csv, pathlib, math

with open('/root/campaign_manifest.json') as f:
    manifest = json.load(f)

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

crate_cost_rows = read_csv('/root/crate_cost.csv')
billing_rows    = read_csv('/root/billing.csv')
override_rows   = read_csv('/root/location_overrides.csv')
suspension_rows = read_csv('/root/suspensions.csv')

ASSUMPTIONS = {
    "dispatches_per_year_6_day": 60,
    "dispatches_per_year_12_day": 30,
    "days_per_dispatch_6_day": 6,
    "days_per_dispatch_12_day": 12,
    "switch_threshold_usd": 11000,
    "override_rule": "highest numeric approved revision with non-empty active_clinics, else default_active_clinics",
    "suspension_rule": "exclude hold campaigns",
}


def as_list(value):
    if value is None:
        return []
    if isinstance(value, list):
        return value
    return [value]


def campaign_iter(manifest_obj):
    """Yield campaigns from either a direct campaigns list/dict or the observed regions layout."""
    direct = manifest_obj.get('campaigns')
    if isinstance(direct, dict):
        for campaign in direct.values():
            yield campaign
    elif isinstance(direct, list):
        for campaign in direct:
            yield campaign

    for region in manifest_obj.get('regions', []):
        campaigns = region.get('campaigns', [])
        if isinstance(campaigns, dict):
            for campaign in campaigns.values():
                yield campaign
        elif isinstance(campaigns, list):
            for campaign in campaigns:
                yield campaign


def non_empty(value):
    return value is not None and str(value).strip() != ''


crate_cost_map = {
    row['crate_tier']: float(row['crate_cost_usd'])
    for row in crate_cost_rows
}

suspended_ids = {
    row['campaign_id']
    for row in suspension_rows
    if row.get('suspension_status', '').strip().lower() == 'hold'
}

all_campaigns = list(campaign_iter(manifest))
retained_campaigns = [
    campaign for campaign in all_campaigns
    if campaign.get('analysis_flag') == 'review'
    and campaign.get('campaign_id') not in suspended_ids
]


def resolve_billing(campaign):
    labels = {str(campaign.get('campaign_name', ''))}
    labels.update(str(label) for label in as_list(campaign.get('alias_labels')))
    matches = [
        row for row in billing_rows
        if row.get('status', '').strip().lower() == 'active'
        and row.get('campaign_label') in labels
    ]
    if not matches:
        raise ValueError(f"No active billing row for {campaign.get('campaign_id')}")
    latest = max(matches, key=lambda row: row.get('cycle_tag', ''))
    return latest, float(latest['payment_per_dispatch_per_clinic_usd'])


def resolve_active_clinics(campaign):
    cid = campaign['campaign_id']
    candidates = []
    for row in override_rows:
        if row.get('campaign_id') != cid:
            continue
        if row.get('state', '').strip().lower() != 'approved':
            continue
        if not non_empty(row.get('revision')) or not non_empty(row.get('active_clinics')):
            continue
        try:
            revision_num = float(row['revision'])
        except ValueError:
            continue
        candidates.append((revision_num, row))
    if not candidates:
        return int(campaign['default_active_clinics'])
    _, latest_row = max(candidates, key=lambda item: item[0])
    return int(float(latest_row['active_clinics']))


def money(value):
    return round(value, 2)


def compute_campaign(campaign):
    days_6, disp_6 = 6, 60
    days_12, disp_12 = 12, 30

    billing_row, payment = resolve_billing(campaign)
    active_clinics = resolve_active_clinics(campaign)
    drug_cost = float(campaign['drug_cost_per_1000_doses_usd'])
    doses_per_day = float(campaign['doses_per_day'])
    crate_tier = str(campaign['crate_tier'])
    crate_cost = crate_cost_map[crate_tier]

    revenue_6 = payment * active_clinics * disp_6
    drug_6 = drug_cost * active_clinics * doses_per_day * days_6 * disp_6 / 1000
    crate_6 = crate_cost * disp_6
    margin_6 = revenue_6 - drug_6 - crate_6

    revenue_12 = payment * active_clinics * disp_12
    drug_12 = drug_cost * active_clinics * doses_per_day * days_12 * disp_12 / 1000
    crate_12 = crate_cost * disp_12
    margin_12 = revenue_12 - drug_12 - crate_12

    rounded_margin_6 = money(margin_6)
    rounded_margin_12 = money(margin_12)

    return {
        "campaign_id": campaign['campaign_id'],
        "campaign_name": campaign['campaign_name'],
        "billing_cycle_tag": billing_row.get('cycle_tag', ''),
        "payment_per_dispatch_per_clinic_usd": money(payment),
        "active_clinics": active_clinics,
        "crate_tier": crate_tier,
        "crate_cost_usd": money(crate_cost),
        "annual_revenue_6_day_usd": money(revenue_6),
        "annual_drug_cost_6_day_usd": money(drug_6),
        "annual_crate_cost_6_day_usd": money(crate_6),
        "annual_margin_6_day_usd": rounded_margin_6,
        "annual_revenue_12_day_usd": money(revenue_12),
        "annual_drug_cost_12_day_usd": money(drug_12),
        "annual_crate_cost_12_day_usd": money(crate_12),
        "annual_margin_12_day_usd": rounded_margin_12,
        "annual_margin_difference_12_minus_6_usd": money(rounded_margin_12 - rounded_margin_6),
    }


campaign_results = sorted(
    (compute_campaign(campaign) for campaign in retained_campaigns),
    key=lambda row: row['campaign_id']
)

total_margin_6 = money(sum(row['annual_margin_6_day_usd'] for row in campaign_results))
total_margin_12 = money(sum(row['annual_margin_12_day_usd'] for row in campaign_results))
total_diff = money(total_margin_12 - total_margin_6)
abs_diff = money(abs(total_diff))
decision = "move_to_12_day" if abs_diff < ASSUMPTIONS['switch_threshold_usd'] else "keep_6_day"

analysis = {
    "assumptions": ASSUMPTIONS,
    "campaigns": campaign_results,
    "totals": {
        "total_margin_6_day_usd": total_margin_6,
        "total_margin_12_day_usd": total_margin_12,
        "total_margin_difference_12_minus_6_usd": total_diff,
        "absolute_margin_difference_usd": abs_diff,
    },
    "decision": decision,
}

with open('/root/vaxcrate_analysis.json', 'w') as f:
    json.dump(analysis, f, indent=2)
    f.write('\n')

summary_lines = [
    f"Total 6-day margin: {total_margin_6:.2f} USD",
    f"Total 12-day margin: {total_margin_12:.2f} USD",
    f"Absolute difference: {abs_diff:.2f} USD",
    f"Decision: {decision}",
]
pathlib.Path('/root/vaxcrate_summary.md').write_text('\n'.join(summary_lines) + '\n')

print(f"Wrote /root/vaxcrate_analysis.json with {len(campaign_results)} campaigns")
print(f"Wrote /root/vaxcrate_summary.md")
print(f"Decision: {decision}")
